const body = $input.item.json.body || $input.item.json;

const formattedAlert = `🚨 *FERTIFLOW CRITICAL CLINICAL ESCALATION* 🚨\n\n` +
  `*Patient Name:* ${body.patient_name || 'Anonymous'}\n` +
  `*Phone Number:* ${body.patient_phone || 'N/A'}\n` +
  `*District / Location:* ${body.patient_district || 'Tamil Nadu'}\n` +
  `*Urgency Level:* ${body.urgency || 'IMMEDIATE'} (L3 Clinical Guardrail)\n` +
  `*Reported Symptom / Reason:* ${body.symptom_or_reason}\n` +
  `*Timestamp:* ${body.timestamp || new Date().toISOString()}\n\n` +
  `⚡ *ACTION REQUIRED:* On-duty fertility specialist Dr. Subha or clinical nurse coordinator must contact this patient immediately.`;

return [{
  json: {
    ...body,
    formatted_alert: formattedAlert,
    status: 'ALERT_BROADCASTED'
  }
}];
